checks.run:
t=$(mktemp -d); ok=1; for b in $(git for-each-ref --format='%(refname:short)' refs/heads); do d=$(mktemp -d "$t/branch.XXXXXX"); git archive "$b" | tar -x -C "$d"; cat > "$d/zz_heldout_test.go" <<'EOF'
package shop

import "testing"

func TestHeldoutPlanHelpers(t *testing.T) {
	if got := Count(nil); got != 0 {
		t.Errorf("Count(nil) = %d", got)
	}
	if got := Count([]Line{{"a", 2}, {"b", 3}}); got != 5 {
		t.Errorf("Count = %d", got)
	}
	for _, c := range []struct{ total, percent, want int }{{1000, -5, 1000}, {1000, 150, 0}, {1000, 15, 850}, {1000, 0, 1000}, {1000, 100, 0}} {
		if got := ApplyCoupon(c.total, c.percent); got != c.want {
			t.Errorf("ApplyCoupon(%d, %d) = %d, want %d", c.total, c.percent, got, c.want)
		}
	}
	cat := Catalog{"a": {SKU: "a", Price: 250}, "b": {SKU: "b", Price: 100}}
	if !cat.Has("a") || cat.Has("z") {
		t.Error("Catalog.Has is wrong")
	}
	if got, err := Subtotal(cat, nil); err != nil || got != 0 {
		t.Errorf("Subtotal(empty) = %d, %v", got, err)
	}
	if got, err := Subtotal(cat, []Line{{"a", 2}, {"b", 1}}); err != nil || got != 600 {
		t.Errorf("Subtotal = %d, %v", got, err)
	}
	if _, err := Subtotal(cat, []Line{{"z", 1}}); err == nil {
		t.Error("Subtotal with an unknown sku should fail")
	}
}
EOF
if (cd "$d" && GOWORK=off go test -count=1 -run Heldout ./... >/dev/null 2>&1); then ok=0; break; fi; done; rm -rf "$t"; exit $ok
